:root {
  --bg: #0f1419;
  --surface: #1a2332;
  --border: #2d3a4f;
  --text: #e8edf4;
  --muted: #8b9cb3;
  --accent: #5b9cf5;
  --accent-hover: #7eb0ff;
}

.admin-shell {
  min-height: 100vh;
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
  line-height: 1.5;
}

.admin-nav {
  display: flex;
  gap: 1rem;
  padding: 1rem 1.5rem;
  border-bottom: 1px solid var(--border);
  background: var(--surface);
}

.admin-nav a {
  color: var(--muted);
  text-decoration: none;
  font-size: 0.9rem;
}

.admin-nav a:hover {
  color: var(--accent-hover);
}

.admin-nav a[data-active='true'] {
  color: var(--accent);
  font-weight: 600;
}

.admin-main {
  padding: 1.5rem;
  max-width: 1200px;
  margin: 0 auto;
}

.admin-toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 1.25rem;
}

.admin-toolbar h1 {
  font-size: 1.35rem;
  font-weight: 600;
  margin: 0 0 0.35rem;
}

.admin-meta {
  font-size: 0.85rem;
  color: var(--muted);
  margin: 0;
}

.sync-form {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 0.35rem;
}

.sync-form button {
  background: var(--accent);
  color: #0a0e14;
  border: none;
  padding: 0.55rem 1rem;
  border-radius: 6px;
  font-weight: 600;
  cursor: pointer;
  font-size: 0.9rem;
}

.sync-form button:hover:not(:disabled) {
  background: var(--accent-hover);
}

.sync-form button:disabled {
  opacity: 0.65;
  cursor: wait;
}

.sync-hint {
  font-size: 0.75rem;
  color: var(--muted);
  max-width: 280px;
  text-align: right;
  margin: 0;
}

.catalog-table-wrap {
  overflow-x: auto;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--surface);
}

.catalog-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.875rem;
}

.catalog-table th,
.catalog-table td {
  text-align: left;
  padding: 0.65rem 0.85rem;
  border-bottom: 1px solid var(--border);
}

.catalog-table th {
  color: var(--muted);
  font-weight: 600;
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.catalog-table tr:last-child td {
  border-bottom: none;
}

.catalog-table tbody tr:hover td {
  background: rgba(91, 156, 245, 0.06);
}

.num {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.overview-cards {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 1rem;
}

.overview-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 1rem 1.1rem;
}

.overview-card h2 {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--muted);
  margin: 0 0 0.35rem;
}

.overview-card p {
  margin: 0;
  font-size: 1.5rem;
  font-weight: 600;
}

