'use client'

import { useFormStatus } from 'react-dom'

export function SyncCatalogSubmit() {
  const { pending } = useFormStatus()

  return (
    <>
      <button type="submit" disabled={pending}>
        {pending ? 'Sync queued…' : 'Sync latest catalog'}
      </button>
      <p className="sync-hint">
        Runs upstream sync in the background. You can keep working; the list may be briefly stale
        until the job finishes and cache tag <code>products</code> is invalidated.
      </p>
    </>
  )
}

